function [b_max] = dipole_field_max(r, lambda_max)
%DIPOLE_FIELD_MAX  The dipole field at magnetic latitude lambda_max: B_max = B0 (R_E/r)^3 sqrt(1 + 3 sin^2 lambda).
%   r: real[km] (passed in m)
%   lambda_max: real[deg] (passed a plain number)
%   returns b_max: real[T] (passed in kg/(s^2 A))
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b_max = 0;
    [b0, tilt] = asils.groups.env.dipole();
    b_max = ((b0 * asils.pc.ipow((6378137 / r), 3)) * asils.pc.sqrt_((1 + (3 * asils.pc.ipow(sin(lambda_max), 2)))));
end
